__NUXT_JSONP__("/think-tanks/noticias/ethos_participa_en_la_conferencia_de_southern_voice_2025_reimaginando_la_arquitectura_del_desarrollo_global", (function(a,b,c,d,e){return {data:[{post:{slug:"ethos_participa_en_la_conferencia_de_southern_voice_2025_reimaginando_la_arquitectura_del_desarrollo_global",title:"Ethos participa en la Conferencia de Southern Voice 2025, Reimaginando la arquitectura del desarrollo global",date:"2025-10-30T21:54:28.788Z",img:"https:\u002F\u002Fucarecdn.com\u002F57175087-7669-4f8d-926d-941250cf7427\u002F-\u002Fcrop\u002F3748x2159\u002F100,218\u002F-\u002Fpreview\u002F","img-alt":"Southern Voice conference 2025",autor:"Ethos",category:"think-tanks",extracto:"Think tanks  de África, Asia, América Latina y el Caribe se reunieron en São Paulo, Brasil para dialogar y generar propuestas que influyan en las políticas y prácticas de desarrollo global desde la perspectiva del Sur Global.",toc:[],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"En São Paulo, Brasil, el 27 y 28 de octubre se realizó la Conferencia de Southern Voice 2025, Reimaginando la arquitectura del desarrollo global, en la que participaron representantes de 71 think tanks de África, Asia, América Latina y el Caribe. Representando a Ethos, acudieron nuestra directora Liliana Alvarado; Mónica Corona, directora de Inclusión y Desarrollo Sostenible, y Néstor Genis, coordinador de Inclusión y Desarrollo Sostenible."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"El encuentro colocó las perspectivas del Sur Global en el centro de las discusiones. A través de sesiones plenarias, temáticas y regionales, se buscó que la evidencia y el conocimiento del Sur orienten las decisiones globales y ocupen un lugar clave en las principales agendas internacionales."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"Además, los asistentes reflexionaron sobre las prioridades del Sur Global en materia de liderazgo y cooperación internacional, la necesidad de construir economías resilientes e inclusivas y los desafíos hacia la Agenda Post-2030. También destacaron la importancia de fortalecer las alianzas Sur-Sur, promover la equidad en la investigación y la innovación, y pasar de la evidencia a la acción para lograr un impacto tangible."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"En el mismo tenor, los representantes de los think tanks discutieron estrategias para enfrentar la desigualdad, impulsar una agenda común frente al cambio climático y fomentar la colaboración regional entre África, Asia, América Latina y el Caribe."}]},{type:a,value:d},{type:b,tag:c,props:{},children:[{type:a,value:"El llamado general fue a construir desde la colectividad, aprovechando el conocimiento y la experiencia de las organizaciones participantes para generar resultados concretos que transformen las políticas y prácticas de desarrollo global."}]}]},dir:"\u002Fnoticias",path:"\u002Fnoticias\u002Fethos_participa_en_la_conferencia_de_southern_voice_2025_reimaginando_la_arquitectura_del_desarrollo_global",extension:".md",createdAt:e,updatedAt:e}}],fetch:{},mutations:[]}}("text","element","p","\n","2025-11-25T01:24:03.266Z")));